/*
 * rdp_timing_model.h - RDP timing model measured on NTSC and PAL consoles
 * (rdp_timing v3-v5). Generated from rdp_timing_model.json by gen_c.py.
 *
 * All costs are in RCP cycles (62.5 MHz), VI off. Multiply by RDP_TM_VI_ON_FACTOR
 * for a frame with the VI scanning out a 16-bit 320x240 buffer.
 *
 * A command list costs RDP_TM_LIST_BASE (list start + Sync_Full) plus the
 * cost of every command:
 *   - set/no-op commands: rdp_tm_state_cmd(); syncs: rdp_tm_sync()
 *   - a rectangle or triangle: rdp_tm_prim_overhead() once, plus
 *     rdp_tm_span() for every span (row) it draws
 *   - loads: rdp_tm_load_block / rdp_tm_load_tile / rdp_tm_load_tlut
 *
 * Made by Nekokabu.
 */
