static const uint8_t rdp_tm_bpp[RDP_TM_NUM_MODES] = {2,4,2,2,4,2,4,2,4,2,2,2,2,4,2,4,4,4,4,2,2,4,2,4,2,2};
/* added for every further 32 pixels beyond 64, in 1/8 cycles */
static const uint16_t rdp_tm_inc32_8[RDP_TM_NUM_MODES] = {144,290,162,258,450,516,516,534,1164,513,714,322,634,1005,891,1032,1014,606,522,579,891,1875,813,1557,549,429};
/* per-primitive overhead (primitives drawn back to back) at widths 4, 16, 64 */
static const float rdp_tm_prim_f[RDP_TM_NUM_MODES][3] = {{4.0,1.0,1.0},{2.5,-2.8,-2.0},{9.2,13.0,13.8},{7.0,19.0,20.1},{0.6,16.8,16.0},{4.8,17.5,14.5},{-1.2,16.0,16.0},{-7.2,-3.9,-6.5},{-0.5,-14.8,-11.8},{-0.5,28.8,22.0},{-1.2,3.2,-6.5},{-2.4,0.2,-1.6},{10.8,34.8,7.4},{5.1,7.0,10.0},{-14.0,-0.1,-1.2},{0.2,-8.0,-20.0},{7.8,6.6,8.9},{13.4,21.6,11.5},{13.8,4.0,-2.0},{14.5,25.0,26.9},{-13.6,-1.2,-3.9},{-2.8,-9.5,-10.2},{-12.1,31.0,-11.8},{-11.8,-4.2,-4.2},{2.5,1.8,-5.4},{4.0,22.0,20.1}};

/* one span of w pixels whose first pixel is at byte address addr (colour image) */
static inline float rdp_tm_span(enum rdp_tm_mode m, uint32_t addr, int w)
{
    if (w <= 0) return 0.0f;
    int phase = (int)(addr & 63) / rdp_tm_bpp[m];
    int k = 0;
    if (w > 64) { k = (w - 33) / 32; w -= 32 * k; }
    return (rdp_tm_row8[m][phase][w - 1] + k * rdp_tm_inc32_8[m]) / 8.0f;
}

/* fixed cost of one rectangle or triangle; w = its (widest) span width */
static inline float rdp_tm_prim_overhead(enum rdp_tm_mode m, int w)
{
    const float *f = rdp_tm_prim_f[m];
    if (w <= 4) return f[0];
    if (w <= 16) return f[0] + (f[1] - f[0]) * (w - 4) / 12.0f;
    if (w <= 64) return f[1] + (f[2] - f[1]) * (w - 16) / 48.0f;
    return f[2];
}

static inline float rdp_tm_state_cmd(int from_dmem) { return from_dmem ? 1.73f : 2.62f; }
/* 0x26 Sync_Load, 0x27 Sync_Pipe, 0x28 Sync_Tile */
static inline float rdp_tm_sync(int cmd_id)
{
    return cmd_id == 0x27 ? 50.0f : cmd_id == 0x28 ? 33.0f : 25.0f;
}

/* loads (without the Sync_Load before them); byte counts/addresses in RDRAM */
static inline float rdp_tm_load_block(int texels16)
{
    int n = texels16 * 2;
    return 13.5f + 0.48f * ((n + 7) / 8) + 22.74f * ((n + 63) / 64);
}
static inline float rdp_tm_load_tile(uint32_t addr, uint32_t stride, int row_bytes, int rows)
{
    int words = 0, blocks = 0;
    for (int i = 0; i < rows; i++) {
        uint32_t b0 = addr + i * stride, b1 = b0 + row_bytes;
        words += (int)((b1 + 7) / 8 - b0 / 8);
        blocks += (int)((b1 + 63) / 64 - b0 / 64);
    }
    return 9.7f + 5.74f * rows + 1.16f * words + 17.44f * blocks;
}
static inline float rdp_tm_load_tlut(int entries) { return 30.4f + 1.061f * entries; }

